"""Licence and source attribution embedded in every generated file.

The output combines Lipas (CC BY 4.0) and OpenStreetMap (ODbL 1.0) data, so
the generated database is distributed under ODbL 1.0. See LICENSE-DATA.md.
"""
from __future__ import annotations

LICENSE_ID = "ODbL-1.0"
LICENSE_URL = "https://opendatacommons.org/licenses/odbl/1-0/"

ATTRIBUTION = [
    "Lipas – University of Jyväskylä, CC BY 4.0 (https://lipas.fi)",
    "© OpenStreetMap contributors, ODbL 1.0 (https://www.openstreetmap.org/copyright)",
    "Regional boundaries: Statistics Finland, CC BY 4.0",
]

# One line, for places with little room (package remarks, KML description, GPX)
SHORT = "Data: Lipas (University of Jyväskylä, CC BY 4.0), © OpenStreetMap contributors (ODbL). Licence: ODbL 1.0."
GPX_AUTHOR = "Lipas (University of Jyväskylä), OpenStreetMap contributors"


def notice_text() -> str:
    """Contents of ATTRIBUTION.txt inside data packages and GPX archives."""
    lines = [
        "Generated by python-lipas2tak-tool (https://github.com/Street3r/python-lipas2tak-tool)",
        "",
        f"This data is made available under the Open Database License (ODbL) 1.0: {LICENSE_URL}",
        "",
        "Sources:",
        *[f"  - {a}" for a in ATTRIBUTION],
        "",
        "Lipas: Lamberg, Anne; Laakso, Tapani. Lipas data. University of Jyväskylä.",
        "https://doi.org/10.17011/jyx/dataset/110418",
        "",
    ]
    return "\n".join(lines)
